// 1. 查询所有焊盘对组
const groups = await eda.pcb_Drc.getAllPadPairGroups();

// 2. 输出每个组的名称和焊盘对
console.log('count:', groups.length);
groups.forEach((g, i) => {
  console.log('[' + i + '] name:', g.name);
  g.padPairs.forEach((pair, j) => {
    console.log('    pair[' + j + ']:', pair[0], '↔', pair[1]);
  });
});
```
